const filterByDate = (sourceRef, dateField = "raw_date") => {
  return computed(() => {
    if (!selectedReportDate.value) return sourceRef.value;

    return sourceRef.value.filter(item => {
      const d = item[dateField];
      if (!d) return false;

      // If already YYYY-MM-DD, compare directly
      if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
        return d === selectedReportDate.value;
      }
      
      // Handle DD/MM/YY HH:mm format from the date field
      if (/^\d{2}\/\d{2}\/\d{2}/.test(d)) {
        const parts = d.split(' ')[0].split('/');
        const year = '20' + parts[2];
        const month = parts[1];
        const day = parts[0];
        const itemDate = `${year}-${month}-${day}`;
        return itemDate === selectedReportDate.value;
      }
      
      return new Date(d).toISOString().split("T")[0] === selectedReportDate.value;
    });
  });
};


const filterByWeek = (sourceRef, dateField = "raw_date") => {
  return computed(() => {
    if (!selectedReportDate.value) return sourceRef.value;

    const selected = new Date(selectedReportDate.value);

    // Compute Monday (week start)
    const day = selected.getDay(); // 0 = Sun, 1 = Mon, ... 6 = Sat
    const diffToMonday = day === 0 ? -6 : 1 - day; 
    const weekStart = new Date(selected);
    weekStart.setDate(selected.getDate() + diffToMonday);

    // Compute Sunday (week end)
    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekStart.getDate() + 6);

    // Convert to YYYY-MM-DD for comparison
    const startStr = weekStart.toISOString().split("T")[0];
    const endStr = weekEnd.toISOString().split("T")[0];

    return sourceRef.value.filter(item => {
      const d = item[dateField];
      if (!d) return false;

      let itemDateStr;

      // Handle DD/MM/YY HH:mm format (like "25/01/26 03:00")
      if (/^\d{2}\/\d{2}\/\d{2}/.test(d)) {
        const parts = d.split(' ')[0].split('/');
        const year = '20' + parts[2];
        const month = parts[1];
        const day = parts[0];
        itemDateStr = `${year}-${month}-${day}`;
      }
      // Handle YYYY-MM-DD format
      else if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
        itemDateStr = d;
      }
      // Handle ISO datetime strings
      else {
        const itemDate = new Date(d);
        if (isNaN(itemDate.getTime())) return false; // Invalid date
        itemDateStr = itemDate.toISOString().split("T")[0];
      }

      return itemDateStr >= startStr && itemDateStr <= endStr;
    });
  });
};


