    isSupervisorLoading.value = true;

    try {
        // Always ensure location is fetched
        if (
            !currentLocation.value.latitude ||
            !currentLocation.value.longitude
        ) {
            await getCurrentLocation();
        }
        if (
            !currentLocation.value.latitude ||
            !currentLocation.value.longitude
        ) {
            throw new Error("Failed to get location. Please enable location services.");
        }

        const payload = {
            user_id: JSON.parse(localStorage.getItem("user")).id,
            store_id: route.params.store_id,
            location: currentLocation.value.address,
            latitude: currentLocation.value.latitude,
            longitude: currentLocation.value.longitude
        };

        await axiosInstance.post('geo-location-attendances', payload);

        showMessage('Successfully reported to site!');
        await getSupervisorCurrentStatus();

    } catch (error) {
